/* 默契題庫解析:"題目|選項A|選項B|選項C|選項D#預設答案索引(可省略)" */
function parseQuiz(list) {
  return (list || []).map(t => { const [body, a] = t.split('#'); const p = body.split('|');
    return { q: p[0], o: p.slice(1), a: a === undefined ? null : Number(a) }; });
}
